def _as_univariate_poly(poly: sp.Poly | sp.Expr, var: sp.Symbol | None = None) -> sp.Poly:
    if isinstance(poly, sp.Poly):
        if poly.is_multivariate:
            if var is None:
                raise ValueError("a variable is required for multivariate expressions")
            return sp.Poly(poly.as_expr(), var, domain="EX")
        return poly
    if var is None:
        symbols = sorted(poly.free_symbols, key=symbol_identity_key)
        if len(symbols) != 1:
            raise ValueError("a variable is required unless the expression is univariate")
        var = symbols[0]
    return sp.Poly(poly, var, domain="EX")


def _root_multiplicities(poly: sp.Poly) -> dict[sp.Expr, int]:
    out: dict[sp.Expr, int] = {}
    try:
        _, factors = sp.factor_list(poly.as_expr())
    except (NotImplementedError, sp.PolynomialError, ValueError, TypeError):
        return out
    var = poly.gens[0]
    for factor_expr, mult in factors:
        factor_poly = sp.Poly(
            factor_expr, var, domain=poly.domain if poly.domain != sp.EX else "EX"
        )
        try:
            roots = sp.real_roots(factor_poly.as_expr())
        except (NotImplementedError, sp.PolynomialError, ValueError):
            roots = []
        for root in roots:
            out[root] = mult
    return out


def rational_intvl_around(root: sp.Expr | AlgebraicRoot | RationalSample) -> RationalInterval:
    """Return a certified rational isolating interval for a real algebraic root.

    The enclosure is derived from exact polynomial isolation.  Decimal
    approximations are never used to manufacture certificate metadata.
    """

    if isinstance(root, (AlgebraicRoot, RationalSample)):
        # A Sample already carries the exact rational certificate we need.
        # In particular, a fiber-certified root must never be reconstructed as
        # a global algebraic expression merely to recover its own enclosure.
        return root.interval
    root = sp.sympify(root)
    if root.is_Rational:
        value = sp.Rational(root)
        return RationalInterval(value, value)
    # ``CRootOf`` already carries a certified rational isolating interval.
    # Recomputing a minimal polynomial and isolating all of its roots is much
    # more expensive, especially for algebraic-coefficient fibers whose
    # elimination polynomial has higher degree than the original fiber.
    if isinstance(root, sp.polys.rootoftools.ComplexRootOf) and root.is_real is True:
        interval = root._get_interval()
        left, right = interval.as_tuple() if hasattr(interval, "as_tuple") else tuple(interval)
        return RationalInterval(sp.Rational(left), sp.Rational(right))
    t = fresh_real_dummy("alpha")
    try:
        minimal = sp.Poly(sp.minpoly(root, t), t, domain=sp.QQ)
        intervals = minimal.intervals(eps=sp.Rational(1, 10**30))
    except (NotImplementedError, sp.PolynomialError, ValueError, TypeError) as exc:
        raise ValueError(
            "could not construct an exact isolating interval for algebraic root"
        ) from exc
    for bounds, _multiplicity in intervals:
        left, right = map(sp.Rational, bounds)
        if compare_exact_reals(root, left) >= 0 and compare_exact_reals(root, right) <= 0:
            return RationalInterval(left, right)
    raise ValueError("minimal-polynomial intervals did not isolate the requested algebraic root")


def _poly_intervals(poly: sp.Poly) -> list[tuple[RationalInterval, int]]:
    try:
        exact_poly = sp.Poly(poly.as_expr(), poly.gens[0], extension=True)
        raw = exact_poly.intervals(eps=sp.Rational(1, 10**30))
    except (
        NotImplementedError,
        sp.PolynomialError,
        sp.polys.polyerrors.DomainError,
        ValueError,
        TypeError,
    ):
        return []
    intervals: list[tuple[RationalInterval, int]] = []
    for bounds, mult in raw:
        left, right = bounds
        intervals.append((RationalInterval(sp.Rational(left), sp.Rational(right)), int(mult)))
    return intervals


def _count_roots_in_interval(
    poly: sp.Poly,
    left: sp.Rational,
    right: sp.Rational,
    *,
    exclude_left: bool = False,
    exclude_right: bool = False,
) -> int:
    """Count roots exactly while optionally excluding root endpoints."""

    if poly.domain in (sp.ZZ, sp.QQ):
        count = _ordinary_root_count(poly, left, right)
    else:
        # Non-rational coefficient domains occur during initial algebraic-coefficient
        # isolation, not repeated refinement. Keep this boundary explicit.
        count = int(poly.count_roots(left, right))
    if exclude_left and poly.eval(left) == 0:
        count -= 1
    if exclude_right and poly.eval(right) == 0:
        count -= 1
    return count


def _trim_excluded_endpoint(
    poly: sp.Poly,
    left: sp.Rational,
    right: sp.Rational,
    *,
    exclude_left: bool,
    exclude_right: bool,
) -> tuple[sp.Rational, sp.Rational]:
    """Move an excluded root endpoint away from a one-root interval."""

    for _ in range(96):
        if not exclude_left and not exclude_right:
            break
        mid = sp.Rational(left + right, 2)
        mid_is_root = poly.eval(mid) == 0
        if mid_is_root:
            # The interval's unique included root is the midpoint unless that
            # root is excluded by construction, which cannot occur for a
            # strict interior midpoint.
            return mid, mid
        if exclude_left:
            right_count = _count_roots_in_interval(poly, mid, right, exclude_right=exclude_right)
            if right_count == 1:
                left = mid
                exclude_left = False
                continue
            right = mid
        elif exclude_right:
            left_count = _count_roots_in_interval(poly, left, mid, exclude_left=exclude_left)
            if left_count == 1:
                right = mid
                exclude_right = False
                continue
            left = mid
    return left, right


def _exact_poly_eval(poly: sp.Poly, point: sp.Rational) -> sp.Expr:
    """Evaluate a rational/integer polynomial through the centralized FLINT bridge."""

    accelerated = flint_eval(poly, point)
    if accelerated is not None:
        return accelerated
    return sp.simplify(poly.eval(point))


def _sign_variations(coefficients: Iterable[sp.Expr]) -> int:
    signs: list[int] = []
    for coeff in coefficients:
        # Descartes transforms in this module have exact rational coefficients.
        # Comparing rationals directly avoids constructing thousands of symbolic
        # ``sign`` functions and triggering SymPy's assumptions engine.
        if coeff.is_Rational:
            if coeff == 0:
                continue
            signs.append(1 if coeff > 0 else -1)
            continue
        value = sp.sign(coeff)
        if value == 0:
            continue
        if value == 1:
            signs.append(1)
        elif value == -1:
            signs.append(-1)
        else:
            raise ValueError("Descartes variation requires ordered rational coefficients")
    return sum(left != right for left, right in zip(signs, signs[1:], strict=False))


def _descartes_variations_interval(poly: sp.Poly, left: sp.Rational, right: sp.Rational) -> int:
    """Exact Descartes variation count on the open interval ``(left, right)``.

    The Möbius map ``x=(left + right*t)/(1+t)`` maps ``t>0`` onto the interval.
    The transformed coefficients are built by homogeneous Horner evaluation,
    which is quadratic in the degree rather than expanding every binomial term
    separately.
    """

    left, right = sp.Rational(left), sp.Rational(right)
    cache_key = ("descartes-variation", poly_key(poly), left, right)
    cached = CACHE.descartes_variations.get(cache_key)
    if cached is not None:
        return int(cached)

    coeffs = [sp.Rational(coeff) for coeff in poly.all_coeffs()]
    # H_k(t) = (1+t)^k P_k((left + right*t)/(1+t)), where P_k
    # is the degree-k leading truncation.  Thus
    # H_k = (left + right*t) H_{k-1} + a_k (1+t)^k.
    transformed = [coeffs[0]]
    one_plus_t = [sp.Integer(1)]
    for degree, coeff in enumerate(coeffs[1:], start=1):
        previous = transformed
        transformed = [sp.Rational(0)] * (degree + 1)
        for index, value in enumerate(previous):
            transformed[index] += left * value
            transformed[index + 1] += right * value
        one_plus_t = [sp.binomial(degree, index) for index in range(degree + 1)]
        for index, value in enumerate(one_plus_t):
            transformed[index] += coeff * value

    result = _sign_variations(reversed(transformed))
    CACHE.descartes_variations.put(cache_key, result)
    return result


def _cauchy_root_bound(poly: sp.Poly) -> sp.Integer:
    primitive = sp.Poly(poly.clear_denoms(convert=True)[1], poly.gens[0], domain=sp.ZZ)
    leading = abs(int(primitive.LC()))
    if leading == 0:
        return sp.Integer(1)
    tail = [abs(int(coeff)) for coeff in primitive.all_coeffs()[1:]]
    if not tail:
        return sp.Integer(1)
    return sp.Integer(1 + max((value + leading - 1) // leading for value in tail))


def _admissible_descartes_split(
    poly: sp.Poly,
    left: sp.Rational,
    right: sp.Rational,
    parent_variations: int,
) -> sp.Rational:
    """Choose a controlled-height split, preferring an Arb Newton proposal."""

    node_key = ("descartes-node", poly_key(poly), sp.Rational(left), sp.Rational(right))
    cached_node = CACHE.descartes_nodes.get(node_key)
    if cached_node is not None:
        split, cached_parent = cached_node
        if int(cached_parent) == int(parent_variations) and left < split < right:
            return sp.Rational(split)

    candidate = arb_newton_proposal(poly, left, right)
    midpoint = sp.Rational(left + right, 2)
    proposals: list[sp.Rational] = []
    if candidate is not None:
        proposals.append(candidate)
        # Nearby dyadics make Newton proposals robust against landing on a root
        # while keeping coefficient heights controlled.
        width = right - left
        for divisor in (16, 32, 64):
            delta = width / divisor
            if left < candidate - delta < right:
                proposals.append(candidate - delta)
            if left < candidate + delta < right:
                proposals.append(candidate + delta)
    proposals.append(midpoint)

    best = midpoint
    best_score: tuple[int, int, int] | None = None
    for proposal in proposals:
        if not left < proposal < right or _exact_poly_eval(poly, proposal) == 0:
            continue
        try:
            left_v = _descartes_variations_interval(poly, left, proposal)
            right_v = _descartes_variations_interval(poly, proposal, right)
        except ValueError:
            continue
        # Prefer exact variation conservation, then balanced cluster separation,
        # then low rational height.
        score = (
            abs((left_v + right_v) - parent_variations),
            max(left_v, right_v),
            int(proposal.p).bit_length() + int(proposal.q).bit_length(),
        )
        if best_score is None or score < best_score:
            best = proposal
            best_score = score
    CACHE.descartes_nodes.put(node_key, (best, int(parent_variations)))
    return best


def _flint_squarefree_part(poly: sp.Poly) -> sp.Poly:
    derivative = poly.diff()
    common = flint_gcd(poly, derivative)
    if common is None or common.degree() <= 0:
        return poly
    quotient = sp.exquo(poly, common)
    return sp.Poly(quotient.as_expr(), poly.gens[0], domain=poly.domain)


def _separate_factor_interval_from_other_roots(
    factor: sp.Poly,
    full_poly: sp.Poly,
    interval: RationalInterval,
) -> RationalInterval:
    """Shrink a one-factor-root interval until it isolates one root of ``full_poly``.

    Square-free factor isolation can legitimately end at a root belonging to a
    different factor.  Public ``AlgebraicRoot`` intervals must nevertheless
    isolate exactly one root of the original polynomial, including endpoint
    semantics.
    """

    if interval.is_point():
        return interval
    left, right = interval.left, interval.right
    for _ in range(128):
        if _count_roots_in_interval(full_poly, left, right) == 1:
            return RationalInterval(left, right)
        midpoint = sp.Rational(left + right, 2)
        if _exact_poly_eval(factor, midpoint) == 0:
            return RationalInterval(midpoint, midpoint)
        left_count = _count_roots_in_interval(factor, left, midpoint)
        right_count = _count_roots_in_interval(factor, midpoint, right)
        if left_count == 1 and right_count == 0:
            right = midpoint
        elif right_count == 1 and left_count == 0:
            left = midpoint
        else:
            raise ArithmeticError("factor interval lost its unique-root invariant")
    raise ArithmeticError("could not separate a factor root from roots of other factors")


def _isolate_rational_coeff_roots(poly: sp.Poly) -> list[tuple[RationalInterval, int]]:
    """Cluster-aware Newton--Descartes initial isolation over ZZ/QQ.

    Descartes variations are the common cheap certificate.  Sturm counting is
    used only when a node remains ambiguous after subdivision and to verify each
    final one-root interval.  Arb contributes adaptive Newton proposals only;
    all accepted intervals are exact rational certificates.
    """

    rational_poly = sp.Poly(poly.as_expr(), poly.gens[0], domain=sp.QQ)
    residual = rational_poly
    isolated: list[tuple[RationalInterval, int]] = []
    rational_roots = flint_rational_roots(rational_poly) or ()
    for root, multiplicity in rational_roots:
        isolated.append((RationalInterval(root, root), multiplicity))
        divisor = sp.Poly(
            (rational_poly.gens[0] - root) ** multiplicity, rational_poly.gens[0], domain=sp.QQ
        )
        residual = residual.exquo(divisor)
    if residual.degree() <= 0:
        isolated.sort(key=lambda item: (item[0].left, item[0].right))
        return isolated
    common = flint_gcd(residual, residual.diff())
    if common is not None and common.degree() <= 0:
        factors = [(residual, 1)]
    else:
        try:
            factors = residual.sqf_list()[1]
        except (sp.PolynomialError, ValueError, TypeError):
            factors = [(_flint_squarefree_part(residual), 1)]

    for factor, multiplicity in factors:
        factor = sp.Poly(factor.as_expr(), factor.gens[0], domain=sp.QQ)
        if factor.degree() <= 0:
            continue
        if factor.degree() == 1:
            root = sp.Rational(-factor.TC(), factor.LC())
            isolated.append((RationalInterval(root, root), int(multiplicity)))
            continue
        bound = _cauchy_root_bound(factor)
        left = -sp.Rational(bound)
        right = sp.Rational(bound)
        # Ensure the outer endpoints are not roots before applying the open-
        # interval Descartes transform.
        while _exact_poly_eval(factor, left) == 0 or _exact_poly_eval(factor, right) == 0:
            bound *= 2
            left, right = -sp.Rational(bound), sp.Rational(bound)

        stack: list[tuple[sp.Rational, sp.Rational, int, int]] = []
        initial_v = _descartes_variations_interval(factor, left, right)
        stack.append((left, right, initial_v, 0))
        factor_intervals: list[RationalInterval] = []
        while stack:
            node_left, node_right, variations, depth = stack.pop()
            if variations == 0:
                continue
            if variations == 1:
                # Final verification is Sturm-based; it is not on
                # the common subdivision path.
                if _count_roots_in_interval(factor, node_left, node_right) == 1:
                    factor_intervals.append(RationalInterval(node_left, node_right))
                    continue
            if depth >= 80:
                count = _count_roots_in_interval(factor, node_left, node_right)
                if count == 0:
                    continue
                if count == 1:
                    factor_intervals.append(RationalInterval(node_left, node_right))
                    continue

            split = _admissible_descartes_split(factor, node_left, node_right, variations)
            split_value = _exact_poly_eval(factor, split)
            if split_value == 0:
                factor_intervals.append(RationalInterval(split, split))
                left_v = _descartes_variations_interval(factor, node_left, split)
                right_v = _descartes_variations_interval(factor, split, node_right)
            else:
                left_v = _descartes_variations_interval(factor, node_left, split)
                right_v = _descartes_variations_interval(factor, split, node_right)

            # Ambiguous non-progressing nodes get one exact Sturm count to avoid
            # exponential Descartes subdivision around pathological clusters.
            if max(left_v, right_v) >= variations and depth >= 12:
                left_count = _count_roots_in_interval(
                    factor, node_left, split, exclude_right=split_value == 0
                )
                right_count = _count_roots_in_interval(
                    factor, split, node_right, exclude_left=split_value == 0
                )
                left_v = min(left_v, left_count) if left_count <= 1 else left_v
                right_v = min(right_v, right_count) if right_count <= 1 else right_v
                if left_count == 1:
                    factor_intervals.append(RationalInterval(node_left, split))
                    left_v = 0
                if right_count == 1:
                    factor_intervals.append(RationalInterval(split, node_right))
                    right_v = 0

            if right_v > 0:
                stack.append((split, node_right, right_v, depth + 1))
            if left_v > 0:
                stack.append((node_left, split, left_v, depth + 1))

        for interval in factor_intervals:
            interval = _separate_factor_interval_from_other_roots(factor, rational_poly, interval)
            isolated.append((interval, int(multiplicity)))

    isolated.sort(key=lambda item: (item[0].left, item[0].right))
    # A final cross-factor disjointness/root-count check catches accidental
    # overlap and ensures multiplicity metadata did not alter root identities.
    for interval, _multiplicity in isolated:
        if interval.is_point():
            if _exact_poly_eval(rational_poly, interval.left) != 0:
                raise ArithmeticError("point isolation certificate is not a root")
        elif _count_roots_in_interval(rational_poly, interval.left, interval.right) != 1:
            raise ArithmeticError("Descartes isolation certificate failed final verification")
    return isolated


def _isolate_algebraic_coeff_roots(poly: sp.Poly) -> list[tuple[RationalInterval, int]]:
    """Isolate real roots over an exact algebraic coefficient field.

    SymPy can count real roots over ``QQ<alpha>`` efficiently even where its
    general ``RootOf`` association machinery is expensive.  This routine uses
    those exact counts to construct pairwise ordered rational isolating
    intervals.  It never uses a floating-point approximation to choose a root.
    """

    exact_poly = sp.Poly(poly.as_expr(), poly.gens[0], extension=True)
    try:
        factors = exact_poly.sqf_list()[1]
    except (NotImplementedError, sp.PolynomialError, ValueError, TypeError):
        factors = [(exact_poly, 1)]
    isolated: list[tuple[RationalInterval, int]] = []
    for factor, multiplicity in factors:
        total = int(factor.count_roots(-sp.oo, sp.oo))
        if total == 0:
            continue
        bound = sp.Integer(1)
        for _ in range(128):
            if (
                factor.eval(-bound) != 0
                and factor.eval(bound) != 0
                and int(factor.count_roots(-bound, bound)) == total
            ):
                break
            bound *= 2
        else:
            raise NotImplementedError("could not bound all exact real roots")

        def recurse(
            left: sp.Rational,
            right: sp.Rational,
            count: int,
            *,
            exclude_left: bool = False,
            exclude_right: bool = False,
            _factor: sp.Poly = factor,
            _multiplicity: int = multiplicity,
        ) -> None:
            """Bisect an isolating interval until every retained interval contains one real root."""
            if count <= 0:
                return
            if count == 1:
                left, right = _trim_excluded_endpoint(
                    _factor,
                    left,
                    right,
                    exclude_left=exclude_left,
                    exclude_right=exclude_right,
                )
                isolated.append((RationalInterval(left, right), int(_multiplicity)))
                return
            mid = sp.Rational(left + right, 2)
            mid_is_root = _factor.eval(mid) == 0
            if mid_is_root:
                isolated.append((RationalInterval(mid, mid), int(_multiplicity)))
            left_count = _count_roots_in_interval(
                _factor,
                left,
                mid,
                exclude_left=exclude_left,
                exclude_right=mid_is_root,
            )
            right_count = _count_roots_in_interval(
                _factor,
                mid,
                right,
                exclude_left=mid_is_root,
                exclude_right=exclude_right,
            )
            recurse(
                left,
                mid,
                left_count,
                exclude_left=exclude_left,
                exclude_right=mid_is_root,
            )
            recurse(
                mid,
                right,
                right_count,
                exclude_left=mid_is_root,
                exclude_right=exclude_right,
            )

        recurse(-sp.Rational(bound), sp.Rational(bound), total)
    isolated.sort(key=lambda item: (item[0].left, item[0].right))
    return isolated


def _dedupe_sorted_roots(roots: Iterable[sp.Expr]) -> list[sp.Expr]:
    """Sort and deduplicate exact real algebraic roots without numerics."""

    ordered = sorted(roots, key=cmp_to_key(compare_exact_reals))
    unique: list[sp.Expr] = []
    for root in ordered:
        if not unique or compare_exact_reals(unique[-1], root) != 0:
            unique.append(root)
    return unique


def _adaptive_newton_candidate(
    poly: sp.Poly, left: sp.Rational, right: sp.Rational
) -> sp.Rational | None:
    """Return a Newton split proposal; correctness is verified by exact counts.

    Rational coefficient fibers use an exact rational Newton step.  Algebraic
    coefficient fibers use progressively more precise numerical proposals.
    Approximation is never a certificate: callers accept a proposal only after
    an exact root-count check.
    """

    midpoint = sp.Rational(left + right, 2)
    derivative = poly.diff()
    try:
        value = poly.eval(midpoint)
        slope = derivative.eval(midpoint)
    except (sp.PolynomialError, ValueError, TypeError):
        return None
    if certified_zero(value) is True:
        return midpoint
    if certified_zero(slope) is True:
        return None
    candidate = sp.cancel(midpoint - value / slope)
    if candidate.is_Rational:
        candidate = sp.Rational(candidate)
        if left < candidate < right:
            return candidate
        return None

    # Approximate arithmetic is used only to propose a rational split point.
    # Increasing precision mirrors the adaptive-precision strategy of fast
    # Descartes/Newton isolators while the exact Sturm count below remains the
    # source of certification.
    for digits in (20, 40, 80):
        try:
            numerical = sp.N(candidate, digits)
            if numerical.is_real is not True:
                continue
            proposed = sp.Rational(str(numerical))
        except (TypeError, ValueError, ArithmeticError):
            continue
        if left < proposed < right:
            return proposed
    return None


def _ordinary_sturm_sequence(poly: sp.Poly) -> tuple[sp.Poly, ...]:
    """Return a cached squarefree Sturm sequence for an exact univariate polynomial."""
    key = ("ordinary-root-sturm", poly_key(poly))
    cached = CACHE.root_sturm_sequences.get(key)
    if cached is not None:
        return cached  # type: ignore[return-value]
    exact = sp.Poly(poly.as_expr(), poly.gens[0], domain=poly.domain).sqf_part()
    if exact.degree() <= 0:
        sequence = (exact,)
    else:
        items = [exact, exact.diff()]
        while not items[-1].is_zero:
            remainder = -items[-2].rem(items[-1])
            if remainder.is_zero:
                break
            items.append(remainder)
        sequence = tuple(items)
    CACHE.root_sturm_sequences.put(key, sequence)
    return sequence


def _ordinary_sturm_variation(poly: sp.Poly, value: sp.Rational) -> int:
    """Return a cached Sturm variation at an exact rational endpoint."""
    q = sp.Rational(value)
    key = ("ordinary-root-variation", poly_key(poly), q)
    cached = CACHE.sturm_variations.get(key)
    if cached is not None:
        return int(cached[1])
    signs: list[int] = []
    for element in _ordinary_sturm_sequence(poly):
        evaluated = element.eval(q)
        if evaluated == 0:
            signs.append(0)
            continue
        if getattr(evaluated, "is_positive", None) is True:
            signs.append(1)
        elif getattr(evaluated, "is_negative", None) is True:
            signs.append(-1)
        else:
            sign = sp.sign(evaluated)
            if sign not in (-1, 1):
                raise ValueError("could not certify ordinary Sturm endpoint sign")
            signs.append(int(sign))
    nonzero = [sign for sign in signs if sign]
    variation = sum(a != b for a, b in zip(nonzero, nonzero[1:], strict=False))
    CACHE.sturm_variations.put(key, (tuple(signs), variation))
    return variation


def _ordinary_intvl_cert_key(
    poly: sp.Poly, left: sp.Rational, right: sp.Rational
) -> tuple[object, ...]:
    return ("ordinary-root-interval", poly_key(poly), sp.Rational(left), sp.Rational(right))


def _remember_ordinary_intvl_count(
    poly: sp.Poly, left: sp.Rational, right: sp.Rational, root_count: int
) -> None:
    CACHE.root_intvl_certs.put(_ordinary_intvl_cert_key(poly, left, right), int(root_count))


def _ordinary_root_count(poly: sp.Poly, left: sp.Rational, right: sp.Rational) -> int:
    """Count roots in ``(left, right]``, reusing the persistent isolation tree."""
    left, right = sp.Rational(left), sp.Rational(right)
    if left > right:
        left, right = right, left
    intvl_key = _ordinary_intvl_cert_key(poly, left, right)
    cached_count = CACHE.root_intvl_certs.get(intvl_key)
    if cached_count is not None:
        return int(cached_count)
    root_count = _ordinary_sturm_variation(poly, left) - _ordinary_sturm_variation(poly, right)
    CACHE.root_intvl_certs.put(intvl_key, int(root_count))
    return int(root_count)


def _rec_ordinary_intvl_split(
    poly: sp.Poly,
    left: sp.Rational,
    split_point: sp.Rational,
    right: sp.Rational,
    left_root_count: int,
    total_root_count: int,
) -> None:
    """Persist both children of a certified isolation-tree split."""
    right_root_count = int(total_root_count) - int(left_root_count)
    _remember_ordinary_intvl_count(poly, left, split_point, left_root_count)
    _remember_ordinary_intvl_count(poly, split_point, right, right_root_count)
    _remember_ordinary_intvl_count(poly, left, right, total_root_count)
    CACHE.root_intvl_splits.put(
        _ordinary_intvl_cert_key(poly, left, right),
        (sp.Rational(split_point), int(left_root_count), int(right_root_count)),
    )


def _verified_single_root_refinement(
    poly: sp.Poly, left: sp.Rational, right: sp.Rational
) -> tuple[sp.Rational, sp.Rational]:
    """Contract a certified one-root interval using Newton, then bisection.

    A Newton proposal is accepted only when exact root counting proves which
    side contains the unique root.  If the proposal is unavailable or provides
    little contraction, ordinary bisection supplies the same deterministic
    deterministic fallback used by this routine.
    """

    node_key = ("ordinary-root-refinement", poly_key(poly), sp.Rational(left), sp.Rational(right))
    cached_node = CACHE.root_refinement_nodes.get(node_key)
    if cached_node is not None:
        return cached_node  # type: ignore[return-value]

    # Newton contraction pays off most on already localized/clustered roots.
    # Wide easy intervals stay on the cheaper bisection path, avoiding the
    # exact root-count overhead of a speculative Newton proposal.
    candidate = None
    if right - left <= sp.Rational(1, 4):
        candidate = _adaptive_newton_candidate(poly, left, right)
    if candidate is not None:
        try:
            candidate_value = poly.eval(candidate)
            if certified_zero(candidate_value) is True:
                result = (candidate, candidate)
                CACHE.root_refinement_nodes.put(node_key, result)
                return result
            left_count = _ordinary_root_count(poly, left, candidate)
            _rec_ordinary_intvl_split(poly, left, candidate, right, left_count, 1)
            if left_count == 1:
                proposed = (left, candidate)
            else:
                proposed = (candidate, right)
            # Avoid replacing a cheap bisection by a Newton point that barely
            # contracts the interval.
            if proposed[1] - proposed[0] <= (right - left) / 2:
                CACHE.root_refinement_nodes.put(node_key, proposed)
                return proposed
        except (
            NotImplementedError,
            sp.PolynomialError,
            sp.polys.polyerrors.DomainError,
            ValueError,
            TypeError,
        ):
            pass

    midpoint = sp.Rational(left + right, 2)
    if poly.eval(midpoint) == 0:
        result = (midpoint, midpoint)
    else:
        left_count = _ordinary_root_count(poly, left, midpoint)
        _rec_ordinary_intvl_split(poly, left, midpoint, right, left_count, 1)
        if left_count >= 1:
            result = (left, midpoint)
        else:
            result = (midpoint, right)
    CACHE.root_refinement_nodes.put(node_key, result)
    return result


def isolate_real_roots(
    poly: sp.Poly | sp.Expr, var: sp.Symbol | None = None
) -> tuple[AlgebraicRoot, ...]:
    """Return explicit algebraic samples for the real roots of a univariate polynomial."""

    univar = _as_univariate_poly(poly, var)
    if univar.degree() <= 0:
        return ()
    key = (poly_key(univar), univar.gens[0])
    CACHE.stats.calls += 1
    cached = CACHE.roots.get(key)
    if cached is not None:
        CACHE.stats.cache_hits += 1
        return cached  # type: ignore[return-value]
    CACHE.stats.cache_misses += 1

    if univar.domain in (sp.ZZ, sp.QQ):
        exact_intervals = _isolate_rational_coeff_roots(univar)
        samples = tuple(
            AlgebraicRoot(
                polynomial=univar,
                interval=interval,
                root_index=index,
                multiplicity=multiplicity,
                root_expr=None,
            )
            for index, (interval, multiplicity) in enumerate(exact_intervals)
        )
        CACHE.roots.put(key, samples)
        return samples

    # Exact algebraic-coefficient domains are isolated directly into ordered,
    # pairwise-disjoint rational certificates.  This avoids constructing,
    # sorting, and deduplicating radical/RootOf expressions merely to recover
    # identities that the defining polynomial and root index already provide.
    try:
        exact_intervals = _isolate_algebraic_coeff_roots(univar)
    except (
        NotImplementedError,
        sp.PolynomialError,
        sp.polys.polyerrors.DomainError,
        sp.polys.polyerrors.PolynomialDivisionFailed,
        ValueError,
        TypeError,
    ):
        exact_intervals = []
    if exact_intervals:
        samples = tuple(
            AlgebraicRoot(
                polynomial=univar,
                interval=interval,
                root_index=index,
                multiplicity=multiplicity,
                root_expr=None,
            )
            for index, (interval, multiplicity) in enumerate(exact_intervals)
        )
        CACHE.roots.put(key, samples)
        return samples

    expr = sp.expand(univar.as_expr())
    roots_preordered = False
    try:
        raw_roots = sp.real_roots(expr)
        roots_preordered = True
    except (NotImplementedError, sp.PolynomialError, ValueError):
        # Linear and quadratic algebraic-coefficient fibers have simple exact
        # radical representations that remain usable as coefficients at later
        # CAD levels.  Prefer those to opaque interval-root selectors.
        raw_roots = []
        solved_simple = False
        if univar.degree() <= 2:
            try:
                roots_with_mult = sp.roots(expr, univar.gens[0])
                solved_simple = (
                    sum(int(mult) for mult in roots_with_mult.values()) == univar.degree()
                )
                if solved_simple:
                    for root, multiplicity in roots_with_mult.items():
                        reality = root.is_real
                        if reality is None:
                            try:
                                reality = compare_exact_reals(sp.im(root), 0) == 0
                            except ValueError:
                                solved_simple = False
                                break
                        if reality is True:
                            raw_roots.extend([sp.simplify(root)] * int(multiplicity))
            except (NotImplementedError, sp.PolynomialError, ValueError, TypeError):
                solved_simple = False

        if not solved_simple:
            try:
                exact_intervals = _isolate_algebraic_coeff_roots(univar)
            except (
                NotImplementedError,
                sp.PolynomialError,
                sp.polys.polyerrors.DomainError,
                ValueError,
                TypeError,
            ):
                exact_intervals = []
            if exact_intervals:
                samples = tuple(
                    AlgebraicRoot(
                        polynomial=univar,
                        interval=interval,
                        root_index=index,
                        multiplicity=multiplicity,
                        root_expr=None,
                    )
                    for index, (interval, multiplicity) in enumerate(exact_intervals)
                )
                CACHE.roots.put(key, samples)
                return samples

            # Final exact fallback for low-degree domains where root counting is
            # not available.  Radical roots are accepted only if their reality
            # and ordering can themselves be certified exactly.
            solved_low_degree = False
            if univar.degree() <= 4:
                try:
                    roots_with_mult = sp.roots(expr, univar.gens[0])
                    solved_low_degree = (
                        sum(int(mult) for mult in roots_with_mult.values()) == univar.degree()
                    )
                    if solved_low_degree:
                        for root, multiplicity in roots_with_mult.items():
                            reality = root.is_real
                            if reality is None:
                                try:
                                    reality = compare_exact_reals(sp.im(root), 0) == 0
                                except ValueError:
                                    solved_low_degree = False
                                    break
                            if reality is True:
                                raw_roots.extend([sp.simplify(root)] * int(multiplicity))
                except (
                    NotImplementedError,
                    sp.PolynomialError,
                    ValueError,
                    TypeError,
                ):
                    solved_low_degree = False
            if not solved_low_degree:
                raise NotImplementedError(
                    "exact real-root isolation is unavailable for this polynomial"
                ) from None
    if roots_preordered:
        roots = []
        for root in raw_roots:
            if not roots or root != roots[-1]:
                roots.append(root)
    else:
        roots = _dedupe_sorted_roots(raw_roots)
    intervals = _poly_intervals(univar)
    multiplicities = _root_multiplicities(univar)
    samples: list[AlgebraicRoot] = []
    for index, root in enumerate(roots):
        mult = next(
            (
                m
                for candidate, m in multiplicities.items()
                if certified_equal(candidate, root) is True
            ),
            1,
        )
        interval = rational_intvl_around(root)
        if index < len(intervals):
            interval, interval_mult = intervals[index]
            mult = interval_mult or mult
        samples.append(
            AlgebraicRoot(
                polynomial=univar,
                interval=interval,
                root_index=index,
                multiplicity=mult,
                root_expr=root,
            )
        )
    result = tuple(samples)
    CACHE.roots.put(key, result)
    return result


def _qq_univariate(poly: sp.Poly | sp.Expr, var: sp.Symbol | None = None) -> sp.Poly:
    univar = _as_univariate_poly(poly, var)
    try:
        return sp.Poly(univar.as_expr(), univar.gens[0], domain=sp.QQ)
    except (sp.PolynomialError, sp.polys.polyerrors.CoercionFailed, ValueError, TypeError) as exc:
        raise TypeError("certified interval predicates require a polynomial over QQ") from exc


def rational_between_algebraic_reals(
    left: AlgebraicRoot | RationalSample | sp.Expr,
    right: AlgebraicRoot | RationalSample | sp.Expr,
    *,
    max_refinements: int = 128,
) -> sp.Rational:
    """Return a certified rational strictly between two exact real algebraic values.

    Certified intervals drive separation.  Once the left certificate ends
    strictly before the right certificate begins, no further root refinement is
    performed.  While certificates overlap, only one obstructing interval is
    refined per iteration.
    """

    sample_types = (AlgebraicRoot, RationalSample)
    left_sample = left if isinstance(left, sample_types) else None
    right_sample = right if isinstance(right, sample_types) else None
    left_expr = None if left_sample is not None else sp.sympify(left)
    right_expr = None if right_sample is not None else sp.sympify(right)

    lint = left_sample.interval if left_sample is not None else rational_intvl_around(left_expr)
    rint = right_sample.interval if right_sample is not None else rational_intvl_around(right_expr)
    lroot = left if isinstance(left, AlgebraicRoot) else None
    rroot = right if isinstance(right, AlgebraicRoot) else None
    if lroot is not None and lroot.fiber_context is not None:
        cached = lroot.fiber_context.best_root_intvl(lroot.root_index)
        if cached is not None and lint.left <= cached.left and cached.right <= lint.right:
            lint = cached
    if rroot is not None and rroot.fiber_context is not None:
        cached = rroot.fiber_context.best_root_intvl(rroot.root_index)
        if cached is not None and rint.left <= cached.left and cached.right <= rint.right:
            rint = cached

    for _ in range(max_refinements + 1):
        if lint.right < rint.left:
            return sp.Rational(lint.right + rint.left, 2)
        if lint.left > rint.right:
            raise ValueError("expected left < right")
        if lint.is_point() and rint.is_point():
            if lint.left >= rint.left:
                raise ValueError("expected left < right")
            return sp.Rational(lint.left + rint.left, 2)

        # Refine only the certificate that most obstructs separation.  This
        # avoids repeatedly narrowing both already-ordered roots merely to pick
        # a rational sector sample.
        left_width = lint.right - lint.left
        right_width = rint.right - rint.left
        refine_left = not lint.is_point() and (rint.is_point() or left_width >= right_width)
        if refine_left:
            if lroot is not None:
                lroot = refine_root_once(lroot, reason="sector construction")
                lint = lroot.interval
                if lint.right < rint.left:
                    mark_refinement_decisive("sector construction")
            else:
                mid = sp.Rational(lint.left + lint.right, 2)
                if left_expr is not None and compare_exact_reals(left_expr, mid) <= 0:
                    lint = RationalInterval(lint.left, mid)
                else:
                    lint = RationalInterval(mid, lint.right)
        elif not rint.is_point():
            if rroot is not None:
                rroot = refine_root_once(rroot, reason="sector construction")
                rint = rroot.interval
                if lint.right < rint.left:
                    mark_refinement_decisive("sector construction")
            else:
                mid = sp.Rational(rint.left + rint.right, 2)
                if right_expr is not None and compare_exact_reals(right_expr, mid) <= 0:
                    rint = RationalInterval(rint.left, mid)
                else:
                    rint = RationalInterval(mid, rint.right)

    raise ArithmeticError("could not separate exact algebraic values by a rational point")


def certified_sign_stable_root_neighborhood(
    root: AlgebraicRoot,
    companions: Sequence[sp.Poly | sp.Expr],
    *,
    max_refinements: int = 128,
) -> SignStableRootNeighborhood:
    """Shrink an isolating interval until every nonzero companion has fixed sign.

    The root polynomial is kept isolated exactly.  A companion that vanishes at
    the distinguished root is rejected because no nonzero sign can be stable on
    a neighborhood containing that root.
    """

    variable = root.variable
    qq_companions = tuple(_qq_univariate(poly, variable) for poly in companions)
    root_expr = root.as_expr()
    signs: list[int] = []
    for poly in qq_companions:
        value = sp.simplify(poly.as_expr().subs(variable, root_expr))
        relation = compare_exact_reals(value, 0)
        if relation == 0:
            raise ValueError("a companion polynomial vanishes at the distinguished root")
        signs.append(1 if relation > 0 else -1)

    current = refresh_sign_root(root)
    refinement_chain = 0
    for _ in range(max_refinements + 1):
        interval_cert = certify_polynomial_root_interval(
            current.polynomial, current.interval.left, current.interval.right
        )
        if interval_cert.root_count != 1:
            old = current
            current = refine_root_once(current, reason="sign exclusion")
            if current.interval != old.interval:
                record_sign_refinement_advance("sign-stable neighborhood", old)
                refinement_chain += 1
            continue
        stable = True
        for poly in qq_companions:
            cert = certify_polynomial_root_interval(
                poly, current.interval.left, current.interval.right
            )
            if cert.root_count != 0:
                stable = False
                break
        if stable:
            if refinement_chain:
                mark_refinement_decisive("sign exclusion")
                record_sign_refinement_chain("sign-stable neighborhood", refinement_chain)
            return SignStableRootNeighborhood(
                current, current.interval, tuple(signs), qq_companions
            )
        old = current
        current = refine_root_once(current, reason="sign exclusion")
        if current.interval != old.interval:
            record_sign_refinement_advance("sign-stable neighborhood", old)
            refinement_chain += 1
    raise ArithmeticError("could not construct a sign-stable rational root neighborhood")


def _sign_intvl_cert_key(root: AlgebraicRoot) -> tuple[object, ...]:
    """Return the stable cache key for a coordinate's shared sign interval."""
    from .cache import sample_identity_key

    return ("sign-interval", sample_identity_key(root))


def publish_sign_intvl(root: AlgebraicRoot) -> None:
    """Publish a certified narrowing for reuse by every sign evaluator."""
    key = _sign_intvl_cert_key(root)
    cached = CACHE.sign_intvl_certs.get(key)
    if cached is None:
        CACHE.sign_intvl_certs.put(key, root.interval)
        return
    if (
        root.interval.width < cached.width
        and root.interval.left >= cached.left
        and root.interval.right <= cached.right
    ):
        CACHE.sign_intvl_certs.put(key, root.interval)


def refresh_sign_root(root: AlgebraicRoot) -> AlgebraicRoot:
    """Refresh a coordinate from the strongest shared sign certificate."""
    cached = CACHE.sign_intvl_certs.get(_sign_intvl_cert_key(root))
    if cached is None:
        publish_sign_intvl(root)
        return root
    if (
        cached.width < root.interval.width
        and cached.left >= root.interval.left
        and cached.right <= root.interval.right
    ):
        return replace(root, interval=cached)
    publish_sign_intvl(root)
    return root


def refresh_sign_samples(samples: Sequence[Sample]) -> list[Sample]:
    """Refresh every algebraic coordinate before a sign-refinement chain."""
    return [
        refresh_sign_root(sample) if isinstance(sample, AlgebraicRoot) else sample
        for sample in samples
    ]


def refine_root_once(root: AlgebraicRoot, *, reason: str = "root isolation") -> AlgebraicRoot:
    """Make one certified partition refinement of ``root``.

    Internal decision procedures use this primitive only after their target
    predicate remains undecided.  Repeated contraction is therefore driven by
    separation/sign/isolation certificates rather than a caller-selected batch
    size.
    """
    before = root.interval
    if reason == "sign exclusion":
        root = refresh_sign_root(root)
        before = root.interval
    refined = refine_isol_intvl(root, steps=None)
    advanced = refined.interval != before
    record_refinement_request(reason, advanced=advanced)
    if reason == "sign exclusion" and advanced:
        publish_sign_intvl(refined)
    return refined


def refine_isol_intvl(root: AlgebraicRoot, *, steps: int | None = 4) -> AlgebraicRoot:
    """Return the same root with a narrower certified rational interval.

    Opaque and ``CRootOf`` samples use verified Newton contraction once their
    intervals are localized enough for it to pay off.  Approximate arithmetic
    may propose a rational split for algebraic-coefficient fibers, but exact
    root counts certify every accepted contraction.  Readable explicit
    algebraic expressions retain the cheaper direct-comparison path.
    """

    refinement_count = 1 if steps is None else max(steps, 0)
    if root.interval.is_point():
        return root
    left, right = root.interval.left, root.interval.right

    # Fiber roots are refined by Sturm root counts over the certified parent
    # algebraic tower.  This handles simple and repeated roots uniformly and
    # avoids expression reconstruction or uniform rational-grid searches.
    context = root.fiber_context
    if context is not None:
        try:
            interval = context.isolate_root(root.root_index, left, right, steps=refinement_count)
            CACHE.stats.refinements += max(refinement_count, 1)
            return AlgebraicRoot(
                root.polynomial,
                interval,
                root.root_index,
                root.multiplicity,
                root.root_expr,
                context,
            )
        except (
            ArithmeticError,
            NotImplementedError,
            sp.PolynomialError,
            sp.polys.polyerrors.DomainError,
            ValueError,
            TypeError,
        ):
            pass

    # Explicit radicals and other readily comparable algebraic expressions are
    # already cheap to refine.  Keep this path free of Newton/root-count setup.
    from .samples import tower_expression_guard_active

    if (
        not tower_expression_guard_active()
        and root.root_expr is not None
        and not isinstance(root.root_expr, sp.polys.rootoftools.ComplexRootOf)
    ):
        expr = root.as_expr()
        for _ in range(refinement_count):
            CACHE.stats.refinements += 1
            mid = sp.Rational(left + right, 2)
            if compare_exact_reals(expr, mid) <= 0:
                right = mid
            else:
                left = mid
        return AlgebraicRoot(
            root.polynomial,
            RationalInterval(left, right),
            root.root_index,
            root.multiplicity,
            root.root_expr,
            root.fiber_context,
        )

    try:
        poly = sp.Poly(root.polynomial.as_expr(), root.variable, extension=True)
        if _ordinary_root_count(poly, left, right) == 1:
            for _ in range(refinement_count):
                CACHE.stats.refinements += 1
                left, right = _verified_single_root_refinement(poly, left, right)
                if left == right:
                    break
            return AlgebraicRoot(
                root.polynomial,
                RationalInterval(left, right),
                root.root_index,
                root.multiplicity,
                root.root_expr,
                root.fiber_context,
            )
    except (
        NotImplementedError,
        sp.PolynomialError,
        sp.polys.polyerrors.DomainError,
        ValueError,
        TypeError,
    ):
        pass

    # Parent-aware roots never escape into global expression reconstruction.
    # If both tower-sign refinement and the already-specialized univariate root
    # count are unavailable, the certificate needs a stronger tower operation.
    if root.fiber_context is not None:
        raise ArithmeticError(
            "could not refine fiber root without reconstructing a global algebraic expression"
        )

    if tower_expression_guard_active():
        raise ArithmeticError(
            "could not refine algebraic root inside a fiber tower without expression reconstruction"
        )

    # A widened or otherwise non-isolating interval cannot use a one-root count
    # as its identity.  Recover the exact ordered-root expression and fall back
    # to comparison-based bisection.
    CACHE.stats.number_field_refinement_fallbacks += 1
    expr = root.as_expr()
    for _ in range(refinement_count):
        CACHE.stats.refinements += 1
        mid = sp.Rational(left + right, 2)
        if compare_exact_reals(expr, mid) <= 0:
            right = mid
        else:
            left = mid
    return AlgebraicRoot(
        root.polynomial,
        RationalInterval(left, right),
        root.root_index,
        root.multiplicity,
        root.root_expr,
    )


def root_multiplicity(root: AlgebraicRoot) -> int:
    return root.multiplicity


# Root-certificate construction/replay is separate from isolation/refinement.
from ._root_certification import (  # noqa: E402, F401
    certify_polynomial_root_interval,
    verify_polynomial_root_interval_certificate,
)
